 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    rbar = next(r for r in range(h) if all(x == 3 for x in grid[r]))
    cbar = next(c for c in range(w) if all(grid[r][c] == 3 for r in range(h)))
    out = []
    for r in range(h):
        row = []
        for c in range(w):
            if r == rbar or c == cbar:
                row.append(3)
            else:
                row.append(4 if max(abs(r-rbar), abs(c-cbar)) % 2 == 0 else 0)
        out.append(row)
    return out
